import { Metadata } from "next";
import Link from "next/link";
import TrackerClient from "./TrackerClient";

const CANONICAL = "https://www.trayago.in/tracker";

// 1. Technical SEO Metadata for Tracker Portal
export const metadata: Metadata = {
  title: "Train Tracker & Destination Wake-Up Alarm | Trayago",
  description:
    "Track your train journey on Trayago and set a destination wake-up alarm so you do not miss your stop. Follow journey progress, station timings, and delay updates by train number.",
  alternates: {
    canonical: CANONICAL,
  },
  keywords:
    "train tracker, train tracking, train tracker India, train destination alarm, train arrival alarm, wake up alarm for train, train stop alarm, train journey tracker",
  robots: {
    index: true,
    follow: true,
  },
  openGraph: {
    type: "website",
    title: "Train Tracker & Destination Wake-Up Alarm | Trayago",
    description:
      "Track your train journey and get alerted before you reach your destination station.",
    url: CANONICAL,
    siteName: "Trayago",
  },
  twitter: {
    card: "summary_large_image",
    title: "Train Tracker & Destination Wake-Up Alarm",
    description:
      "Track your train journey and get alerted before you reach your destination station.",
  },
};

// 2. Single source of truth for FAQ — rendered visibly AND as FAQPage JSON-LD
const TRACKER_FAQS: { q: string; a: string }[] = [
  {
    q: "What is a train tracker?",
    a: "A train tracker follows a train's progress along its route on a given day. You enter the train number and it shows where the train has been reported, which station is next, how it is running against the timetable, and the station-by-station journey ahead.",
  },
  {
    q: "How does Trayago's train tracker work?",
    a: "Enter a train number and select Track Live. Trayago loads the current running information for that train and shows a journey timeline with station timings and delay information. Recently tracked train numbers are saved in your browser so you can return to them quickly.",
  },
  {
    q: "What is a train destination wake-up alarm?",
    a: "It is an alert tied to the last station on your train's journey timeline. Once enabled for a tracked train, Trayago monitors the journey's progress and alerts you as the train approaches your destination, so you have time to gather your luggage and prepare to get off.",
  },
  {
    q: "Can Trayago alert me before I reach my destination?",
    a: "Yes. Enable the destination wake-up alarm after tracking your train. The alert is designed to reach you as the train nears the destination station rather than at the moment of arrival. Keep the tab open for the alarm to remain active.",
  },
  {
    q: "Does Trayago guarantee exact arrival times?",
    a: "No. Timings shown are based on the scheduled timetable and the latest reported running information, and a train's delay can change while it is en route. Treat arrival estimates and alarm timing as guidance, and confirm platform numbers with official station announcements.",
  },
  {
    q: "How is the train tracker different from live train running status?",
    a: "The tracker is built around following a journey you are on, with the destination wake-up alarm and quick access to recently tracked trains. Live train running status focuses on checking a train's current status in detail, including a map view, date selection, and auto-refreshing station information.",
  },
];

export default function TrackerPage() {
  // 3. Structured Data Schemas
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: "https://www.trayago.in",
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "Train Tracker",
        item: CANONICAL,
      },
    ],
  };

  const webPageSchema = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: "Train Tracker & Destination Wake-Up Alarm",
    description:
      "Track a train journey by train number and set a destination wake-up alarm to avoid missing your stop.",
    url: CANONICAL,
    inLanguage: "en-IN",
    isPartOf: {
      "@type": "WebSite",
      name: "Trayago",
      url: "https://www.trayago.in",
    },
  };

  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: TRACKER_FAQS.map(({ q, a }) => ({
      "@type": "Question",
      name: q,
      acceptedAnswer: {
        "@type": "Answer",
        text: a,
      },
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}
      />
      <TrackerClient />

      {/* Explanatory SEO content — rendered below the tracker so the tool stays primary */}
      <section
        aria-labelledby="tracker-guide-heading"
        className="w-full px-4 md:px-8 pb-16"
      >
        <div className="max-w-4xl mx-auto w-full border-t border-subtle pt-12 space-y-10 text-sm text-secondary leading-relaxed">
          <div className="space-y-3">
            <h2 id="tracker-guide-heading" className="text-xl font-black text-main">
              Train tracker and destination wake-up alarm
            </h2>
            <p>
              A <strong>train tracker</strong> follows a service along its route
              on a particular day. Enter the train number above and Trayago
              shows the journey timeline — where the train has been reported,
              which station comes next, station timings, and how it is running
              against the schedule.
            </p>
            <p>
              What makes this page different from a plain status lookup is the{" "}
              <strong>destination wake-up alarm</strong>: an alert built for
              people who are actually on the train and would rather not watch
              their phone for the whole journey.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              How Trayago train tracking works
            </h3>
            <ol className="list-decimal pl-5 space-y-2">
              <li>
                Enter a train number, or pick one from the popular trains list.
              </li>
              <li>
                Select <strong>Track Live</strong> to load current running
                information and the station-by-station journey timeline.
              </li>
              <li>
                Enable the destination alarm if you want to be alerted as the
                train approaches the end of its timeline.
              </li>
            </ol>
            <p>
              Train numbers you have tracked are kept in your browser, so
              returning to a journey later takes one tap. No account is needed
              to track a train.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              How the destination alarm works
            </h3>
            <p>
              The alarm is tied to the final station on the tracked train&apos;s
              journey timeline. Once enabled, Trayago monitors the journey&apos;s
              progress using the same running information shown on this page and
              alerts you as the train nears that station — early enough to
              gather luggage and get ready, rather than at the moment of
              arrival. Keep the tab open for the alarm to stay active, and
              toggle it off at any time.
            </p>
            <p>
              Because it works from reported running information, alarm timing
              is guidance rather than a precise guarantee. A train&apos;s delay
              can change while it is en route.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              Why a train destination alarm is useful
            </h3>
            <p>
              Overnight journeys are the obvious case — falling asleep and waking
              past your station is a common and expensive mistake. It also helps
              on long-distance routes where arrival drifts by hours, at
              unfamiliar stations where you cannot recognise the platform, and on
              early-morning arrivals when nobody in the coach is awake to ask.
              Mostly it removes the need to keep checking the phone, which is the
              whole point of tracking a journey.
            </p>
          </div>

          <div className="space-y-4">
            <h2 className="text-xl font-black text-main">
              Train tracker — frequently asked questions
            </h2>
            <dl className="space-y-5">
              {TRACKER_FAQS.map(({ q, a }) => (
                <div key={q} className="space-y-1.5">
                  <dt className="text-sm font-bold text-main">{q}</dt>
                  <dd className="text-sm text-secondary leading-relaxed">{a}</dd>
                </div>
              ))}
            </dl>
          </div>

          <div className="space-y-3 border-t border-subtle pt-8">
            <h3 className="text-base font-bold text-main">Related tools</h3>
            <p>
              For a detailed view with a map, date selection and auto-refreshing
              station information, use{" "}
              <Link
                href="/live"
                className="text-primary font-semibold hover:underline"
              >
                live train running status
              </Link>
              . You can also check a booking with{" "}
              <Link
                href="/pnr"
                className="text-primary font-semibold hover:underline"
              >
                PNR status and confirmation prediction
              </Link>
              , plan a route with the{" "}
              <Link
                href="/"
                className="text-primary font-semibold hover:underline"
              >
                Trayago train search
              </Link>
              , break a long route into connecting segments with the{" "}
              <Link
                href="/split-journey"
                className="text-primary font-semibold hover:underline"
              >
                AI split journey planner
              </Link>
              , check approved station catering prices in the{" "}
              <Link
                href="/rate-list"
                className="text-primary font-semibold hover:underline"
              >
                IRCTC station rate list
              </Link>
              , or track journeys on the{" "}
              <Link
                href="/app"
                className="text-primary font-semibold hover:underline"
              >
                Trayago Android app
              </Link>
              .
            </p>
            <p className="text-xs text-muted">
              Trayago is an independent travel intelligence platform and is not
              affiliated with, endorsed by, or operated by IRCTC or Indian
              Railways. Ticket booking is completed through official booking
              platforms.
            </p>
          </div>
        </div>
      </section>
    </>
  );
}
