'use client';

import React, { useState, useEffect, useRef, Suspense } from 'react';
import { Search, Train, MapPin, Clock, AlertCircle, Loader2, ChevronRight, ChevronDown, Navigation, Cpu, Volume2, Square } from 'lucide-react';
import axios from 'axios';
import { clsx } from 'clsx';
import { useSearchParams } from 'next/navigation';
import { API_BASE } from '@/lib/api';
import { showDOMToast } from '@/utils/share';
import { voiceService, VoiceLanguage } from '@/lib/voiceService';

const API_BASE_URL = API_BASE;

const POPULAR_TRAINS = [
  { number: '12002', name: 'NDLS-BPL Shatabdi' },
  { number: '12952', name: 'MMCT-NDLS Rajdhani' },
  { number: '12301', name: 'HWH-NDLS Rajdhani' },
  { number: '12626', name: 'Kerala Express' },
  { number: '12260', name: 'HWH-NDLS Duronto' },
  { number: '12004', name: 'LJN-NDLS Shatabdi' }
];

function TrackerContent() {
  const searchParams = useSearchParams();
  const initialTrainNo = searchParams.get('trainNo') || '';
  
  const [trainNo, setTrainNo] = useState(initialTrainNo);
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [alarm, setAlarm] = useState<any>(null);
  const [alarmLoading, setAlarmLoading] = useState(false);
  const [alarmLang, setAlarmLang] = useState<VoiceLanguage>('hi');
  const [isVoicePlaying, setIsVoicePlaying] = useState(false);
  const lastScrolledTrainRef = useRef<string | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      setAlarmLang(voiceService.getLanguage() === 'en' ? 'en' : 'hi');
    }
  }, []);

  // Sync across components when voiceService or alarm sets language
  useEffect(() => {
    const handleSync = (e: any) => {
      const newL = e.detail?.lang;
      if (newL === 'hi' || newL === 'en') {
        setAlarmLang(newL);
      }
    };
    window.addEventListener('trayago:language-change', handleSync);
    return () => window.removeEventListener('trayago:language-change', handleSync);
  }, []);

  // Stop speech playback on component unmount
  useEffect(() => {
    return () => {
      voiceService.stop();
    };
  }, []);

  // Reset voice playback state when data changes
  useEffect(() => {
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
    }
  }, [data]);
  const [showPastStations, setShowPastStations] = useState(false);

  const playTrackerVoice = (langToUse: VoiceLanguage) => {
    if (!data) return;

    const currentStn =
      data.current_station ||
      data.journey_timeline?.find((s: any) => s.is_current === true)?.station_name;
    const destStn =
      data.journey_timeline?.[data.journey_timeline.length - 1]?.station_name ||
      data.destination_station_name;

    let delayVal: number | undefined = undefined;
    if (typeof data.delay_minutes === 'number') {
      delayVal = data.delay_minutes;
    } else if (data.delay_minutes !== undefined && data.delay_minutes !== null && (data.delay_minutes as any) !== '') {
      const parsed = parseInt(String(data.delay_minutes), 10);
      if (!isNaN(parsed)) delayVal = parsed;
    }

    setIsVoicePlaying(true);
    voiceService.speakLiveTrackingStatus(
      {
        trainNo: data.train_number || trainNo,
        trainName: data.train_name,
        statusMessage: data.status_summary || data.status_message,
        currentStation: currentStn,
        nextStation: data.next_station,
        delayMinutes: delayVal,
        expectedArrival: data.expected_arrival,
        destinationStation: destStn,
        speed: data.speed ?? data.speed_kmh ?? undefined,
      },
      langToUse,
      'female',
      () => {
        setIsVoicePlaying(false);
      }
    );
  };

  const handleToggleVoiceStatus = () => {
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
      return;
    }

    playTrackerVoice(alarmLang);
  };

  const handleSelectAlarmLang = (newLang: VoiceLanguage) => {
    setAlarmLang(newLang);
    voiceService.setLanguage(newLang);
    const wasPlaying = isVoicePlaying;
    voiceService.stop();
    setIsVoicePlaying(false);
    if (wasPlaying) {
      setTimeout(() => {
        playTrackerVoice(newLang);
      }, 250);
    }
  };

  // Auto-scroll to current station or tracker status card ONLY on initial train search load
  useEffect(() => {
    const currentTrain = data?.train_number || trainNo;
    if (data && currentTrain && lastScrolledTrainRef.current !== currentTrain) {
      lastScrolledTrainRef.current = currentTrain;
      const timer = setTimeout(() => {
        const el = document.getElementById('current-tracker-station') || document.getElementById('tracker-status-card');
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 250);
      return () => clearTimeout(timer);
    }
  }, [data?.train_number, trainNo]);

  const fetchAlarmForTrain = async (num: string) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/alarms`);
      if (response.data.success && Array.isArray(response.data.data)) {
        const activeAlarm = response.data.data.find(
          (a: any) => a.train_no === num && a.enabled === true
        );
        setAlarm(activeAlarm || null);
      }
    } catch (err) {
      console.error('Failed to fetch alarms:', err);
    }
  };

  const handleToggleAlarm = async () => {
    if (!data) return;
    const destStation = data.journey_timeline?.[data.journey_timeline.length - 1];
    if (!destStation?.station_code) {
      showDOMToast('Could not resolve destination station code.', 'error');
      return;
    }

    setAlarmLoading(true);
    if (alarm) {
      try {
        const response = await axios.patch(`${API_BASE_URL}/alarms/${alarm.id}`, { enabled: false });
        if (response.data.success) {
          setAlarm(null);
          showDOMToast('Destination alarm disabled.', 'info');
        } else {
          showDOMToast(response.data.error || 'Failed to update alarm.', 'error');
        }
      } catch (err: any) {
        showDOMToast(err.response?.data?.error || 'Failed to disable alarm.', 'error');
      } finally {
        setAlarmLoading(false);
      }
    } else {
      try {
        const response = await axios.post(`${API_BASE_URL}/alarms`, {
          train_no: data.trainNo || trainNo,
          destination_station: destStation.station_code,
          radius_km: 20.0
        });
        if (response.data.success) {
          setAlarm(response.data.data);
          const armedMsg = alarmLang === 'hi'
            ? `🔔 अलार्म सेट हो गया! ${destStation.station_name || destStation.station_code} से 20 किमी पहले तेज़ सायरन, आवाज़ और वाइब्रेशन बजेगा। कृपया फोन वॉल्यूम फुल रखें।`
            : `🔔 Wake-Up Alarm Armed! A loud siren, voice alert & vibration will trigger 20 km before ${destStation.station_name || destStation.station_code}. Keep device volume high.`;
          showDOMToast(armedMsg, 'success');
        } else {
          showDOMToast(response.data.error || 'Failed to enable alarm.', 'error');
        }
      } catch (err: any) {
        showDOMToast(err.response?.data?.error || 'Failed to set alarm.', 'error');
      } finally {
        setAlarmLoading(false);
      }
    }
  };

  useEffect(() => {
    try {
      const saved = localStorage.getItem('trayago_recent_tracks');
      if (saved) {
        const list = JSON.parse(saved);
        if (Array.isArray(list)) {
          const stringList = list
            .map((item: any) => (typeof item === 'string' ? item : (item?.trainNo || item?.number || item?.train || '')))
            .filter((x: string) => typeof x === 'string' && x.length > 0);
          setRecentSearches(stringList);
        }
      }
    } catch (e) {
      console.warn('Failed to load recent searches:', e);
    }
  }, []);

  const saveRecentSearch = (num: string) => {
    if (!num) return;
    try {
      const saved = localStorage.getItem('trayago_recent_tracks');
      let list = saved ? JSON.parse(saved) : [];
      if (!Array.isArray(list)) list = [];
      list = [num, ...list.filter((x: string) => x !== num)].slice(0, 5);
      localStorage.setItem('trayago_recent_tracks', JSON.stringify(list));
      setRecentSearches(list);
    } catch (e) {
      console.warn('Failed to save recent search:', e);
    }
  };

  const clearRecentSearches = () => {
    try {
      localStorage.removeItem('trayago_recent_tracks');
      setRecentSearches([]);
    } catch (e) {
      console.warn('Failed to clear recent searches:', e);
    }
  };

  useEffect(() => {
    if (initialTrainNo) {
      handleTrackDirect(initialTrainNo);
    }
  }, [initialTrainNo]);

  const handleTrackDirect = async (num: string) => {
    setLoading(true);
    setError(null);
    saveRecentSearch(num);
    try {
      const response = await axios.get(`${API_BASE_URL}/trains/live/${num}`);
      if (response.data.success) {
        setData(response.data.data);
        fetchAlarmForTrain(num);
      } else {
        setError(response.data.message || 'Live status unavailable for this train.');
      }
    } catch (err) {
      setError('Failed to connect to tracking server. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleTrack = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!trainNo) return;

    setLoading(true);
    setError(null);
    saveRecentSearch(trainNo);
    try {
      const response = await axios.get(`${API_BASE_URL}/trains/live/${trainNo}`);
      if (response.data.success) {
        setData(response.data.data);
        fetchAlarmForTrain(trainNo);
      } else {
        setError(response.data.message || 'Live status unavailable for this train.');
      }
    } catch (err) {
      setError('Failed to connect to tracking server. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleQuickTrack = (num: string) => {
    setTrainNo(num);
    handleTrackDirect(num);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-20">
      {/* Search Section */}
      <div className="bg-card border border-subtle rounded-3xl p-8 shadow-2xl">
        <h1 className="text-3xl md:text-4xl font-black text-main tracking-tight mb-2">Train Tracker &amp; Destination Alarm</h1>
        <p className="text-sm sm:text-base text-secondary mb-8 leading-relaxed max-w-2xl font-normal">
          Enter a 5-digit Indian Railways train number to follow its journey progress, station timings and delay updates — and set a destination wake-up alarm so you do not miss your stop.
        </p>

        <form onSubmit={handleTrack} className="relative group">
          <input
            type="text"
            placeholder="Enter 5-digit Train Number (e.g. 12002 or 12952)"
            value={trainNo}
            onChange={(e) => setTrainNo(e.target.value)}
            className="w-full bg-input border border-subtle rounded-2xl py-5 px-6 pl-14 text-main focus:outline-none focus:border-blue-500 transition-all text-lg font-bold placeholder:text-zinc-500 dark:placeholder:text-zinc-400"
          />
          <Train className="absolute left-5 top-1/2 -translate-y-1/2 text-muted group-focus-within:text-blue-500 transition-colors" size={24} />
          <button 
            type="submit"
            className="absolute right-3 top-1/2 -translate-y-1/2 bg-blue-600 hover:bg-blue-500 text-main font-bold py-3 px-8 rounded-xl transition-all shadow-lg active:scale-95 flex items-center"
            disabled={loading}
          >
            {loading ? <Loader2 className="animate-spin" size={20} /> : 'Track Live'}
          </button>
        </form>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-6 flex flex-col space-y-4 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex items-start space-x-4">
            <AlertCircle className="text-red-500 mt-1 shrink-0" />
            <div>
              <h3 className="text-red-500 font-bold uppercase tracking-widest text-xs mb-1">Tracking Error</h3>
              <p className="text-zinc-400 text-sm leading-relaxed">{error}</p>
            </div>
          </div>
          {trainNo && (
            <div className="flex flex-col sm:flex-row gap-3 pt-2">
              <a
                href={`https://enquiry.indianrail.gov.in/mntes/`}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center justify-center space-x-2 bg-blue-600/20 hover:bg-blue-600/30 border border-blue-500/30 text-blue-400 font-bold py-2.5 px-5 rounded-xl transition-all text-xs"
              >
                <Train size={14} />
                <span>Check on IRCTC Official</span>
              </a>
              <a
                href={`https://www.railyatri.in/live-train-status/${trainNo}`}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center justify-center space-x-2 bg-input hover:bg-card border border-subtle text-main font-bold py-2.5 px-5 rounded-xl transition-all text-xs"
              >
                <MapPin size={14} />
                <span>RailYatri Live Status</span>
              </a>
            </div>
          )}
        </div>
      )}

      {data && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-500">
           {/* Current Status Header */}
           <div id="tracker-status-card" className="bg-card border border-subtle rounded-3xl p-6 border-l-4 border-l-blue-500 overflow-hidden relative">
              <div className="absolute top-0 right-0 p-8 opacity-5">
                 <Navigation size={120} className="rotate-45" />
              </div>
              
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 relative z-10">
                 <div>
                    <h2 className="text-2xl font-black text-main flex items-center">
                       {data.train_name || `Train ${data.train_number || trainNo}`}
                       <span className="ml-3 text-sm bg-input text-muted px-3 py-1 rounded-full border border-subtle">#{data.train_number || trainNo}</span>
                    </h2>
                    <p className="text-success font-bold text-sm mt-1">{data.status_summary || data.status_message || 'Running'}</p>
                 </div>
                 <div className="flex items-center gap-2 flex-wrap w-full sm:w-auto justify-between sm:justify-end">
                    {/* 1-Click Language Switch: Hindi & English */}
                    <div className="flex items-center gap-1 bg-input/80 p-0.5 rounded-xl border border-subtle text-[11px]" role="group" aria-label="Select Voice Announcement Language">
                       <button
                         type="button"
                         onClick={() => handleSelectAlarmLang('hi')}
                         aria-pressed={alarmLang === 'hi'}
                         className={clsx(
                           "px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation",
                           alarmLang === 'hi' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                         )}
                       >
                         🇮🇳 हिंदी
                       </button>
                       <button
                         type="button"
                         onClick={() => handleSelectAlarmLang('en')}
                         aria-pressed={alarmLang === 'en'}
                         className={clsx(
                           "px-2.5 py-1 rounded-lg font-bold transition-all cursor-pointer touch-manipulation",
                           alarmLang === 'en' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                         )}
                       >
                         🌐 English
                       </button>
                    </div>
                    {/* User-Triggered Listen Status Control */}
                    <button
                      type="button"
                      onClick={handleToggleVoiceStatus}
                      aria-label={isVoicePlaying ? "Stop live tracking voice announcement" : "Listen to live train status"}
                      aria-pressed={isVoicePlaying}
                      className={clsx(
                        "min-h-[44px] min-w-[44px] px-3.5 py-2 rounded-xl text-xs font-bold transition-all border flex items-center gap-2 cursor-pointer active:scale-95 touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500",
                        isVoicePlaying
                          ? "bg-blue-600 text-white border-blue-400 animate-pulse shadow-md font-black"
                          : "bg-blue-500/10 hover:bg-blue-500/20 text-blue-500 border-blue-500/30 hover:border-blue-500/50"
                      )}
                    >
                      {isVoicePlaying ? (
                        <>
                          <Square size={13} className="fill-current text-white" />
                          <span>{alarmLang === 'hi' ? 'रुकिए' : 'Stop'}</span>
                        </>
                      ) : (
                        <>
                          <Volume2 size={15} />
                          <span>{alarmLang === 'hi' ? 'स्थिति सुनें' : 'Listen Status'}</span>
                        </>
                      )}
                    </button>

                    <div className="text-right">
                       <p className="text-[10px] text-muted font-black uppercase tracking-widest">Last Updated</p>
                       <p className="text-main font-bold">{data.last_updated}</p>
                    </div>
                 </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mt-8">
                 <div className="bg-input p-4 rounded-2xl border border-subtle">
                    <p className="text-[10px] text-muted font-bold uppercase mb-1">Current Stn</p>
                    <p className="text-sm font-bold text-main truncate">
                      {data.current_station || data.journey_timeline?.find((s: any) => s.is_current === true)?.station_name || 'En Route'}</p>
                 </div>
                 <div className="bg-input p-4 rounded-2xl border border-subtle">
                    <p className="text-[10px] text-muted font-bold uppercase mb-1">Next Stn</p>
                    <p className="text-sm font-bold text-primary truncate">{data.next_station}</p>
                 </div>
                 <div className="bg-input p-4 rounded-2xl border border-subtle">
                    <p className="text-[10px] text-muted font-bold uppercase mb-1">Delay</p>
                    <p className={clsx("text-sm font-bold", data.delay_minutes > 0 ? "text-warning" : "text-success")}>
                       {data.delay_minutes === 0 ? 'On Time' : `${data.delay_minutes} Mins`}
                    </p>
                 </div>
                 <div className="bg-input p-4 rounded-2xl border border-subtle">
                    <p className="text-[10px] text-muted font-bold uppercase mb-1">Expected Arr</p>
                    <p className="text-sm font-bold text-main">{data.expected_arrival}</p>
                 </div>
              </div>

               {/* Smart Action: Wake-up Alarm with Discovery Onboarding Spotlight */}
               <div className="relative mt-6 flex flex-col bg-primary/10 p-4 rounded-2xl border border-primary/20 overflow-visible">
                  {/* Spotlight background pulse */}
                  <div className="relative flex items-center justify-between z-10 w-full flex-wrap gap-3">
                     <div className="flex items-center space-x-3">
                        <div className="bg-primary/20 p-2 rounded-lg relative">
                           <Clock className="text-primary" size={20} />
                           {/* Pulsing neon notification badge */}
                           <span className="absolute -top-1 -right-1 flex h-2 w-2">
                              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-success opacity-75"></span>
                              <span className="relative inline-flex rounded-full h-2 w-2 bg-success"></span>
                           </span>
                        </div>
                        <div>
                           <div className="flex items-center gap-1.5 flex-wrap">
                              <p className="text-main font-bold text-sm">Destination Wake-up Alarm</p>
                              <span className="px-1.5 py-0.5 bg-success/15 border border-success/30 rounded text-[9px] font-extrabold text-success uppercase tracking-wide">
                                Loud Siren
                              </span>
                           </div>
                           <p className="text-[10px] text-muted">Alert me 20km before {data.journey_timeline?.[data.journey_timeline.length - 1]?.station_name || data.destination_station_name || 'Destination'}</p>
                        </div>
                     </div>

                     <div className="flex items-center gap-3">
                        {/* Language Selector for Alarm */}
                        <div className="flex items-center gap-1 bg-input/80 p-0.5 rounded-xl border border-subtle text-[11px]">
                           <button
                             type="button"
                             onClick={() => handleSelectAlarmLang('hi')}
                             className={clsx(
                               "px-2 py-1 rounded-lg font-bold transition-all cursor-pointer",
                               alarmLang === 'hi' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                             )}
                           >
                             🇮🇳 हिंदी
                           </button>
                           <button
                             type="button"
                             onClick={() => handleSelectAlarmLang('en')}
                             className={clsx(
                               "px-2 py-1 rounded-lg font-bold transition-all cursor-pointer",
                               alarmLang === 'en' ? "bg-primary text-white shadow-xs" : "text-muted hover:text-main"
                             )}
                           >
                             🌐 English
                           </button>
                        </div>

                        <label className="relative inline-flex items-center cursor-pointer">
                           <input 
                             type="checkbox" 
                             checked={!!alarm?.enabled} 
                             disabled={alarmLoading} 
                             onChange={handleToggleAlarm}
                             className="sr-only peer" 
                           />
                           <div className="w-11 h-6 bg-input border border-subtle peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-subtle after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-muted after:border-subtle after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                        </label>
                     </div>
                  </div>

                  {/* Status Indicator when Armed */}
                  {alarm?.enabled && (
                    <div className="relative mt-2.5 pt-2 border-t border-primary/20 flex items-center gap-2 text-[11px] text-emerald-400 font-bold z-10">
                       <Volume2 size={14} className="animate-pulse" />
                       <span>
                         {alarmLang === 'hi' 
                           ? '🔊 तेज़ सायरन + आवाज़ सक्षम: 20 किमी पहले अलार्म बजेगा।'
                           : '🔊 High-Decibel Siren & Voice Enabled: Will alarm 20 km prior.'}
                       </span>
                    </div>
                  )}

                  {/* Onboarding Spotlight Tooltip */}
                  <div className="relative mt-3 pt-3 border-t border-primary/10 text-[10px] text-secondary flex items-start gap-2 z-10">
                     <span className="text-primary text-xs select-none">💡</span>
                     <p className="leading-relaxed">
                       <strong>Smart Alarm Notice:</strong> Triggers automatically when you are within 20km. Loud siren audio and vibration will play. Please ensure your device volume is up. Keep this tab open.
                     </p>
                  </div>
               </div>
           </div>

           {/* Timeline */}
           <div className="bg-card rounded-3xl p-8 border border-subtle shadow-card">
              <div className="flex items-center justify-between mb-8 border-b border-subtle pb-4">
                 <h3 className="text-lg font-black text-main">Journey Timeline</h3>
                 <span className="text-xs font-bold text-muted bg-input px-3 py-1 rounded-full border border-subtle">
                   {data.journey_timeline?.length || 0} Stations
                 </span>
              </div>

              {(() => {
                 const timeline = data.journey_timeline || [];
                 // Find current station index
                 let curIdx = timeline.findIndex((stn: any) => stn.is_current === true);
                 if (curIdx < 0 && data.current_station) {
                   const cName = String(data.current_station).toLowerCase().trim();
                   curIdx = timeline.findIndex((stn: any) =>
                     String(stn.station_name || '').toLowerCase().trim() === cName ||
                     String(stn.station_code || '').toLowerCase().trim() === cName
                   );
                 }

                 const pastStations = curIdx > 0 ? timeline.slice(0, curIdx) : [];
                 const remainingStations = curIdx >= 0 ? timeline.slice(curIdx) : timeline;

                 const renderTimelineItem = (stn: any, idx: number, isCur: boolean) => (
                    <div 
                       key={idx} 
                       id={isCur ? 'current-tracker-station' : undefined}
                       className={clsx(
                          "relative pl-12 pb-8 group transition-all",
                          stn.is_departed && !isCur ? "opacity-45" : "opacity-100",
                          isCur && "bg-primary/5 rounded-2xl p-4 -ml-4 pl-16 border border-primary/25 shadow-sm"
                       )}
                    >
                       {/* Marker */}
                       <div className={clsx(
                          "absolute left-[9px] top-1.5 w-4 h-4 rounded-full border-2 transition-all z-10",
                          isCur ? "bg-primary border-white scale-125 shadow-lg shadow-primary/50" : 
                          stn.is_departed ? "bg-strong border-subtle" : "bg-card border-strong"
                       )} />
                       
                       {isCur && (
                          <div className="absolute left-[5px] top-0.5 w-6 h-6 rounded-full bg-primary/20 animate-ping" />
                       )}

                       <div className="flex justify-between items-start">
                          <div>
                             <div className="flex items-center gap-2">
                                <p className={clsx(
                                   "font-bold transition-colors",
                                   isCur ? "text-primary text-lg" : "text-main"
                                )}>
                                   {stn.station_name}
                                   <span className="ml-2 text-[10px] text-muted">({stn.station_code})</span>
                                </p>
                                {isCur && (
                                   <span className="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-blue-500/20 text-blue-400 border border-blue-500/30 animate-pulse">
                                      Current Stop
                                   </span>
                                )}
                             </div>
                             <div className="flex items-center space-x-4 mt-1">
                                <span className="text-[10px] text-muted flex items-center">
                                   <Clock size={10} className="mr-1" /> Arr: {stn.arrival_time || '--:--'}
                                </span>
                                <span className="text-[10px] text-muted flex items-center">
                                   <Clock size={10} className="mr-1" /> Dep: {stn.departure_time || '--:--'}
                                </span>
                             </div>
                          </div>
                          
                          {stn.delay_minutes > 0 && (
                             <div className="text-[9px] font-bold text-amber-500/80 uppercase tracking-widest bg-amber-500/5 px-2 py-1 rounded-md border border-amber-500/10">
                                +{stn.delay_minutes}m Delay
                             </div>
                          )}
                       </div>
                    </div>
                 );

                 return (
                    <div className="space-y-0 relative">
                       <div className="absolute left-4 top-2 bottom-2 w-0.5 bg-subtle" />

                       {/* Collapsed departed stations button to bring Current Station to the top */}
                       {pastStations.length > 0 && (
                          <div className="relative pl-12 pb-6 group z-20">
                             <button 
                                type="button"
                                onClick={() => setShowPastStations(!showPastStations)}
                                className="w-full bg-input hover:bg-strong border border-subtle rounded-2xl py-3 px-4 text-xs font-bold text-muted flex items-center justify-between transition-all shadow-sm active:scale-[0.99]"
                             >
                                <span className="flex items-center gap-2">
                                   <Clock size={14} className="text-muted" />
                                   {showPastStations ? 'Hide' : 'View'} {pastStations.length} departed stations
                                </span>
                                <ChevronDown className={`w-4 h-4 transition-transform duration-200 ${showPastStations ? 'rotate-180' : ''}`} />
                             </button>
                          </div>
                       )}

                       {/* Expanded past stations */}
                       {showPastStations && pastStations.map((stn: any, idx: number) => renderTimelineItem(stn, idx, false))}

                       {/* Current station (always top when past stations are collapsed) and upcoming stations */}
                       {remainingStations.map((stn: any, idx: number) => renderTimelineItem(stn, pastStations.length + idx, idx === 0 && curIdx >= 0))}
                    </div>
                 );
              })()}
           </div>
        </div>
      )}

      {/* Popular & Recent Section */}
      {!data && !loading && !error && (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
          
          {/* Recent Searches */}
          {recentSearches.length > 0 && (
            <div className="bg-card border border-subtle rounded-3xl p-6 shadow-md">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-muted">Recent Searches</h3>
                <button 
                  onClick={clearRecentSearches}
                  className="text-xs text-red-500 hover:text-red-400 font-bold transition-colors"
                >
                  Clear History
                </button>
              </div>
              <div className="flex flex-wrap gap-2.5">
                {recentSearches.map((num) => (
                  <button
                    key={num}
                    onClick={() => handleQuickTrack(num)}
                    className="flex items-center space-x-1.5 bg-input hover:bg-strong border border-subtle rounded-xl py-2 px-4 transition-all text-xs font-bold text-main active:scale-95"
                  >
                    <Clock size={12} className="text-muted" />
                    <span>{String(num)}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Popular Trains */}
          <div className="bg-card border border-subtle rounded-3xl p-6 shadow-md">
            <h3 className="text-xs font-bold uppercase tracking-widest text-muted mb-4">Popular Trains</h3>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
              {POPULAR_TRAINS.map((train) => (
                <button
                  key={train.number}
                  onClick={() => handleQuickTrack(train.number)}
                  className="flex flex-col items-start bg-input hover:bg-strong border border-subtle rounded-xl p-3.5 transition-all text-left group active:scale-95"
                >
                  <span className="text-[10px] font-black uppercase tracking-widest text-blue-500 mb-0.5">#{train.number}</span>
                  <span className="text-xs font-bold text-main group-hover:text-blue-500 transition-colors line-clamp-1">{train.name}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Tracker Information Section */}
          <div className="space-y-6">
            <div className="text-center max-w-xl mx-auto space-y-2">
              <h2 className="text-xl font-black text-main tracking-tight">How Trayago Train Tracking Works</h2>
              <p className="text-xs text-secondary leading-relaxed">
                Trayago combines published railway schedules with current running information so you never miss your station. Here is what the tracking suite gives you:
              </p>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="bg-card border border-subtle rounded-3xl p-6 flex items-start space-x-4 shadow-sm hover:border-strong transition-all">
                <div className="bg-blue-600/10 dark:bg-blue-500/10 p-3 rounded-2xl text-blue-500 shrink-0">
                  <Navigation size={22} className="rotate-45" />
                </div>
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-main">Journey Progress Updates</h4>
                  <p className="text-xs text-secondary leading-relaxed">
                    Current running information is refreshed from railway sources so you can see the last reported station and the train&apos;s progress along its route.
                  </p>
                </div>
              </div>

              <div className="bg-card border border-subtle rounded-3xl p-6 flex items-start space-x-4 shadow-sm hover:border-strong transition-all">
                <div className="bg-emerald-600/10 dark:bg-emerald-500/10 p-3 rounded-2xl text-emerald-500 shrink-0">
                  <Clock size={22} />
                </div>
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-main">Station Arrival Estimates</h4>
                  <p className="text-xs text-secondary leading-relaxed">
                    Scheduled station timings are combined with the train&apos;s current delay to estimate when it should reach each upcoming stop.
                  </p>
                </div>
              </div>

              <div className="bg-card border border-subtle rounded-3xl p-6 flex items-start space-x-4 shadow-sm hover:border-strong transition-all">
                <div className="bg-amber-600/10 dark:bg-amber-500/10 p-3 rounded-2xl text-amber-500 shrink-0">
                  <Cpu size={22} />
                </div>
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-main">Delay Information</h4>
                  <p className="text-xs text-secondary leading-relaxed">
                    See how many minutes the train is currently running behind its published timetable, updated as new running information is reported.
                  </p>
                </div>
              </div>

              <div className="bg-card border border-subtle rounded-3xl p-6 flex items-start space-x-4 shadow-sm hover:border-strong transition-all">
                <div className="bg-red-600/10 dark:bg-red-500/10 p-3 rounded-2xl text-red-500 shrink-0">
                  <AlertCircle size={22} />
                </div>
                <div className="space-y-1">
                  <h4 className="text-sm font-bold text-main">Destination Wake-Up Alarm</h4>
                  <p className="text-xs text-secondary leading-relaxed">
                    Set an alarm that alerts you as the train approaches your destination station, giving you time to prepare before you arrive.
                  </p>
                </div>
              </div>
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default function TrackerClient() {
  return (
    <Suspense fallback={<div className="p-20 text-center text-zinc-500 font-bold tracking-widest uppercase text-[10px]">Initializing Radar...</div>}>
      <TrackerContent />
    </Suspense>
  );
}
